

class RobotFrameworkException(Exception):
    pass


class BoardDriverException(RobotFrameworkException):
    def __init__(self, msg=None):
        if not msg:
            msg = "An error occurred in Board Driver"
        # BuiltIn().fail(msg)
        super(BoardDriverException, self).__init__(msg)


class BoardBringupException(RobotFrameworkException):
    def __init__(self, msg=None):
        if not msg:
            msg = "An error occurred in Board Bring up"
        super(BoardBringupException, self).__init__(msg)


class RRBException(RobotFrameworkException):
    def __init__(self, msg=None):
        if not msg:
            msg = "An error occurred in Remote Reset Box"
        super(RRBException, self).__init__(msg)


class SSHException(RobotFrameworkException):
    def __init__(self, msg=None):
        if not msg:
            msg = "An error occurred in Remote Reset Box"
        super(SSHException, self).__init__(msg)


class ConfigParamNotFoundException(RobotFrameworkException):
    def __init__(self, msg=None):
        if not msg:
            msg = "An error occurred while reading config parameters"
        super(ConfigParamNotFoundException, self).__init__(msg)
